using System.Net;using System.Text;using SalekhPos.Desktop.Infrastructure.Management;using Xunit;namespace SalekhPos.Desktop.Tests;public sealed class FiscalizationHttpTests{[Fact]public async Task RejectsInvalidDigest(){var o=Guid.NewGuid(),d=Guid.NewGuid(),b=Guid.NewGuid(),s=Guid.NewGuid();using var c=Client(_=>Json($$"""{"documentId":"{{d:D}}","branchId":"{{b:D}}","saleId":"{{s:D}}","providerKey":"ge","documentType":"receipt","currency":"GEL","grossAmount":1,"payloadSha256":"bad","status":"accepted","providerReference":null,"attemptCount":0,"createdAt":"2026-09-18T08:00:00Z","updatedAt":"2026-09-18T08:00:00Z","attempts":[]}"""));await Assert.ThrowsAsync<InvalidOperationException>(()=>new HttpFiscalizationManager(c).ReadAsync(o,d,default));}private static HttpClient Client(Func<HttpRequestMessage,HttpResponseMessage> f)=>new(new H(f)){BaseAddress=new("https://pos.test/")};private static HttpResponseMessage Json(string x)=>new(HttpStatusCode.OK){Content=new StringContent(x,Encoding.UTF8,"application/json")};private sealed class H(Func<HttpRequestMessage,HttpResponseMessage> f):HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken ct)=>Task.FromResult(f(r));}}